head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL00007_ENG";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil00007_eng.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

        // openResult();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00007_eng.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_60_onclick
 * @description img_60 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_60_onclick = function(e){
    try {
        scwin.submit()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00007_eng.img_60_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_submit
 * @description submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_submit = async function () {
    const sbmOptions = {
        id: "tx_fn_submit",
        method: "post",
        action: "/submission/searchDisclosureDocument.do?method=selectKorDocumentForEnglish",
        ref: "dma_submitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name focusError
 * @description focus Error 처리
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} wrtrptMaindocTpCd wrtrptMaindocTpCd
 * @param {*} xpath xpath
 * @returns {void}
 * @hidden N
 */
scwin.focusError = function (formCd, formVer, wrtrptMaindocTpCd, xpath) {
    const nsArray = eval("getNamespaces_" + formCd + "()");
    (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).focusError === 'function' ? (scwin.openerScwin()).focusError(formCd, formVer, wrtrptMaindocTpCd, xpath, nsArray) : void 0), $c.win.closePopup([formCd, formVer, wrtrptMaindocTpCd, xpath, nsArray]));
};

/**
 * @method
 * @name submit
 * @description submit 처리
 * @returns {void}
 * @hidden N
 */
scwin.submit = function () {
    const url = "/submission/searchDisclosureDocument.do?method=selectKorDocumentForEnglish&applNo=" + dma_disclosureVo.get("applNo") + "" + "&formCd=" + dma_disclosureVo.get("formCd") + "&formVer=" + dma_disclosureVo.get("formVer") + "" + "&exmptObjDisclsYn=" + dma_disclosureVo.get("exmptObjDisclsYn") + "";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.setPageFrameSrc(null, (function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url));
    scwin.close();
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name Namespace
 * @description Namespace 처리
 * @param {*} prefix prefix
 * @param {*} uri uri
 * @returns {void}
 * @hidden N
 */
scwin.Namespace = function (prefix, uri) {
    this.prefix = prefix;
    this.uri = uri;
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
